sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/

function handler({api, event, helpers, imports}) {

    console.log('===== RESERVAS CONSULTADAS =====');

    const reservas =
        api.data.look_up_multiple_records_reservas.results || [];

    console.log('===== DATA RESOURCES =====');
    console.log(api.data);

    console.log('===== LOOKUP RESERVA =====');
    console.log(api.data.look_up_multiple_records_reservas);


    console.log('Quantidade de reservas:', reservas.length);
    console.log('Reservas:', reservas);

    reservas.forEach(function(reserva, index) {

        console.log(
            'Reserva ' + index,
            'Sala:', reserva.sala,
            'Data:', reserva.data,
            'Hora inicial:', reserva.hora_inicial,
            'Hora final:', reserva.hora_final
        );
    });
}
